import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { getMatchId, getLeagueTable } from "../api";

function MatchDetailPage() {
  const { matchId } = useParams();
  const [match, setMatch] = useState(null);
  const [table, setTable] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      const mData = await getMatchId(matchId);
      if (mData) {
        setMatch(mData);
        const tData = await getLeagueTable(mData.league);
        setTable(tData);
      }
      setLoading(false);
    };
    fetchData();
  }, [matchId]);

  if (loading)
    return (
      <div className="h-screen flex items-center justify-center bg-black text-red-600 font-black animate-pulse">
        SYSTEM ANALYZING...
      </div>
    );
  if (!match)
    return <div className="text-center p-20 text-white">Матч не найден</div>;

  const ResultCircle = ({ res }) => {
    const colors = { W: "bg-green-500", D: "bg-gray-500", L: "bg-red-500" };
    return (
      <span
        className={`${colors[res]} w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-black text-white shadow-lg`}
      >
        {res}
      </span>
    );
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 text-white font-sans">
      {/* ГЛАВНЫЙ ЭКРАН: КОМАНДЫ И ФОРМА */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-10 items-center bg-gray-900 p-10 rounded-[40px] border border-gray-800 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-red-600 to-transparent"></div>

        {/* Хозяева */}
        <div className="flex flex-col items-center">
          <img
            src={match.homeTeam.logo_url}
            className="h-32 w-32 object-contain mb-4 drop-shadow-2xl"
            alt=""
          />
          <h1 className="text-3xl font-black uppercase tracking-tighter text-center">
            {match.homeTeam.name_ru || match.homeTeam.name}
          </h1>
          <div className="flex gap-1 mt-4">
            {match.homeTeam.stats_last_5.form.map((r, i) => (
              <ResultCircle key={i} res={r} />
            ))}
          </div>
        </div>

        {/* Центр */}
        <div className="flex flex-col items-center">
          <span className="text-6xl font-black text-gray-800 italic mb-2">
            VS
          </span>
          <span className="text-sm font-bold text-gray-500 bg-gray-800 px-4 py-1 rounded-full uppercase tracking-widest">
            {new Date(match.utcDate).toLocaleDateString("ru-RU", {
              day: "2-digit",
              month: "2-digit",
            })}{" "}
            |{" "}
            {new Date(match.utcDate).toLocaleTimeString([], {
              hour: "2-digit",
              minute: "2-digit",
            })}
          </span>
        </div>

        {/* Гости */}
        <div className="flex flex-col items-center">
          <img
            src={match.awayTeam.logo_url}
            className="h-32 w-32 object-contain mb-4 drop-shadow-2xl"
            alt=""
          />
          <h1 className="text-3xl font-black uppercase tracking-tighter text-center">
            {match.awayTeam.name_ru || match.awayTeam.name}
          </h1>
          <div className="flex gap-1 mt-4">
            {match.awayTeam.stats_last_5.form.map((r, i) => (
              <ResultCircle key={i} res={r} />
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* ЛЕВАЯ КОЛОНКА: АНАЛИТИКА */}
        <div className="lg:col-span-8 space-y-8">
          {/* ПРОГНОЗЫ */}
          <div className="bg-gray-900 rounded-[32px] p-8 border border-gray-800 shadow-xl">
            <h2 className="text-xs font-black text-red-600 uppercase tracking-[0.4em] mb-8">
              Neural Engine Prediction
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              {/* Исходы */}
              <div>
                <div className="flex justify-between mb-4 text-xs font-black uppercase tracking-widest">
                  <span className="text-green-500">
                    П1: {match.prediction.prob_home}%
                  </span>
                  <span className="text-gray-400">
                    X: {match.prediction.prob_draw}%
                  </span>
                  <span className="text-red-500">
                    П2: {match.prediction.prob_away}%
                  </span>
                </div>
                <div className="h-4 w-full bg-gray-800 rounded-full overflow-hidden flex p-0.5 border border-gray-700">
                  <div
                    className="bg-green-500 h-full rounded-l-full"
                    style={{ width: `${match.prediction.prob_home}%` }}
                  ></div>
                  <div
                    className="bg-gray-500 h-full"
                    style={{ width: `${match.prediction.prob_draw}%` }}
                  ></div>
                  <div
                    className="bg-red-500 h-full rounded-r-full"
                    style={{ width: `${match.prediction.prob_away}%` }}
                  ></div>
                </div>
                <div className="mt-6 p-4 bg-black/30 rounded-2xl border border-white/5 flex justify-between items-center">
                  <span className="text-[10px] font-black text-gray-500 uppercase">
                    Ожидаемый результат:
                  </span>
                  <span className="text-xl font-black italic text-white underline decoration-red-600">
                    {match.prediction.exact_score}
                  </span>
                </div>
              </div>

              {/* Тотал */}
              <div>
                <div className="flex justify-between mb-4 text-xs font-black uppercase tracking-widest">
                  <span className="text-blue-400">
                    ТБ 2.5: {match.prediction.total_over_2_5}%
                  </span>
                  <span className="text-gray-600">
                    ТМ 2.5: {100 - match.prediction.total_over_2_5}%
                  </span>
                </div>
                <div className="h-4 w-full bg-gray-800 rounded-full overflow-hidden flex p-0.5 border border-gray-700">
                  <div
                    className="bg-blue-500 h-full rounded-full shadow-[0_0_15px_rgba(59,130,246,0.5)]"
                    style={{ width: `${match.prediction.total_over_2_5}%` }}
                  ></div>
                </div>
                <p className="mt-6 text-[10px] text-gray-500 font-bold uppercase leading-relaxed">
                  Алгоритм предсказывает{" "}
                  {match.prediction.total_over_2_5 > 55 ? "высокую" : "низкую"}{" "}
                  результативность на основе xG-потенциала команд.
                </p>
              </div>
            </div>
          </div>

          {/* ГЛУБОКИЙ АНАЛИЗ */}
          <div className="bg-gray-900 rounded-[32px] p-8 border border-gray-800 shadow-xl">
            <h2 className="text-xs font-black text-gray-500 uppercase tracking-[0.4em] mb-10 text-center">
              Сравнение игровых моделей
            </h2>
            <div className="space-y-10">
              <StatBar
                label="Ожидаемые голы (xG)"
                h={match.homeTeam.stats_last_5.xg}
                a={match.awayTeam.stats_last_5.xg}
              />
              <StatBar
                label="Интенсивность прессинга (PPDA)"
                h={match.homeTeam.stats_last_5.ppda}
                a={match.awayTeam.stats_last_5.ppda}
                reverse
              />
              <StatBar
                label="Глубина атак (Deep)"
                h={match.homeTeam.stats_last_5.deep}
                a={match.awayTeam.stats_last_5.deep}
              />
            </div>
          </div>
        </div>

        {/* ПРАВАЯ КОЛОНКА: ТАБЛИЦА */}
        <div className="lg:col-span-4">
          <div className="bg-gray-900 rounded-[32px] p-6 border border-gray-800 sticky top-28 shadow-xl">
            <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-6">
              Championship Standings
            </h3>
            <div className="space-y-2">
              {table.length > 0 ? (
                table.slice(0, 15).map((row, i) => {
                  const isCurrent =
                    row.team === match.homeTeam.name ||
                    row.team === match.awayTeam.name;
                  return (
                    <div
                      key={i}
                      className={`flex items-center justify-between p-2.5 rounded-xl transition-all ${isCurrent ? "bg-red-600 text-white shadow-lg scale-[1.02] z-10" : "hover:bg-white/5 text-gray-400"}`}
                    >
                      <div className="flex items-center gap-3">
                        <span className="text-[10px] font-mono opacity-50">
                          {i + 1}
                        </span>
                        <span className="text-xs font-black uppercase truncate w-32">
                          {row.team}
                        </span>
                      </div>
                      <div className="flex gap-4 items-center">
                        <span className="text-[10px] font-bold opacity-50">
                          {row.M}
                        </span>
                        <span className="text-xs font-black">{row.PTS}</span>
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="py-10 text-center text-xs text-gray-700 animate-pulse font-black uppercase">
                  Syncing Table...
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

const StatBar = ({ label, h, a, reverse }) => {
  const isHomeBetter = reverse ? h < a : h > a;
  const total = h + a || 1;
  return (
    <div className="relative">
      <div className="flex justify-between items-end mb-3">
        <span
          className={`text-2xl font-black ${isHomeBetter ? "text-white" : "text-gray-700"}`}
        >
          {h.toFixed(2)}
        </span>
        <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-1">
          {label}
        </span>
        <span
          className={`text-2xl font-black ${!isHomeBetter ? "text-white" : "text-gray-700"}`}
        >
          {a.toFixed(2)}
        </span>
      </div>
      <div className="h-1.5 w-full bg-gray-800 rounded-full flex overflow-hidden">
        <div
          className={`h-full transition-all duration-1000 ${isHomeBetter ? "bg-red-600" : "bg-gray-700"}`}
          style={{ width: `${(h / total) * 100}%` }}
        ></div>
        <div
          className={`h-full transition-all duration-1000 ${!isHomeBetter ? "bg-red-600" : "bg-gray-700"}`}
          style={{ width: `${(a / total) * 100}%` }}
        ></div>
      </div>
    </div>
  );
};

export default MatchDetailPage;
